import { Component, TemplateRef, contentChildren, input, viewChild } from '@angular/core';
import { NgTemplateOutlet } from '@angular/common';
import { NzCollapseModule } from 'ng-zorro-antd/collapse';

/** hrm-collapse-panel — 1 panel: header + nội dung (bọc ng-template). */
@Component({
  selector: 'hrm-collapse-panel',
  template: `<ng-template #tpl><ng-content /></ng-template>`,
})
export class HrmCollapsePanel {
  readonly header = input('');
  readonly active = input(false);
  readonly disabled = input(false);
  readonly tpl = viewChild.required<TemplateRef<unknown>>('tpl');
}

/** hrm-collapse — accordion. Dùng hrm-collapse-panel con:
 *  <hrm-collapse><hrm-collapse-panel header="A">...</hrm-collapse-panel></hrm-collapse> */
@Component({
  selector: 'hrm-collapse',
  imports: [NzCollapseModule, NgTemplateOutlet],
  template: `
    <nz-collapse [nzAccordion]="accordion()" [nzBordered]="bordered()">
      @for (p of panels(); track $index) {
        <nz-collapse-panel [nzHeader]="p.header()" [nzActive]="p.active()" [nzDisabled]="p.disabled()">
          <ng-container [ngTemplateOutlet]="p.tpl()" />
        </nz-collapse-panel>
      }
    </nz-collapse>
  `,
  host: { class: 'hrm-collapse' },
})
export class HrmCollapse {
  readonly panels = contentChildren(HrmCollapsePanel);
  readonly accordion = input(false);
  readonly bordered = input(true);
}
